# Surah Al-An'am (chapter 6) — part 3: ayat 24-33 (IDs 813-822)
SURAH = 6

ENTRIES = {
813: (
"دیکھو — انہوں نے اپنے اوپر — جھوٹ کیسے بولا — اور — ان سے — جو وہ گھڑتے تھے — بھٹک گیا",
"""۱۔ مشرکین — خود اپنے خلاف جھوٹے۔
۲۔ ’’انظُرْ كَيْفَ كَذَبُوا عَلَىٰ أَنفُسِهِمْ وَضَلَّ عَنْهُم مَّا كَانُوا يَفْتَرُونَ‘‘ — دیکھو — انہوں نے اپنے اوپر — جھوٹ کیسے بولا — اور — ان سے — جو وہ گھڑتے تھے — بھٹک گیا — یعنی قیامت کے دن ان کا جھوٹ واضح ہوگا — ان کے جھوٹے معبود غائب ہو جائیں گے۔
۳۔ عملی سبق: جھوٹا عقیدہ — خود تمہارے خلاف — ہوگا؛ ہدایت اختیار کرو۔"""
),
814: (
"اور ان میں سے کوئی آپ کی طرف — کان لگاتا ہے — اور ہم نے — ان کے دلوں پر — پردے — ڈال — دیے کہ وہ اسے سمجھ نہ سکیں — اور ان کے کانوں میں — بوجھ — اور اگر وہ ہر نشانی دیکھ لیں پھر بھی وہ — اس — پر — ایمان نہیں لاتے — یہاں تک کہ وہ آپ کے پاس آ کر بحث کرتے ہیں — کافر کہتے ہیں: یہ سوائے پچھلوں کی کہانیوں کے کچھ نہیں",
"""۱۔ کفار — سنتے ہیں مگر سمجھ نہیں پاتے۔
۲۔ ’’وَمِنْهُم مَّن يَسْتَمِعُ إِلَيْكَ وَجَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّۃً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا‘‘ — اور ان میں سے کوئی آپ کی طرف — کان لگاتا ہے — اور ہم نے — ان کے دلوں پر — پردے — ڈال — دیے کہ وہ اسے سمجھ نہ سکیں — اور ان کے کانوں میں — بوجھ — یعنی ان کے دل — ضد اور ہٹ کے باعث — سچ نہیں سمجھتے۔
۳۔ ’’وَإِن يَرَوْا كُلَّ آيَۃٍ لَّا يُؤْمِنُوا بِهَا حَتَّىٰ إِذَا جَاءُوكَ يُجَادِلُونَكَ‘‘ — اور اگر وہ ہر نشانی دیکھ لیں پھر بھی وہ — اس — پر — ایمان نہیں لاتے — یہاں تک کہ وہ آپ کے پاس آ کر بحث کرتے ہیں — یعنی نشانیاں بے اثر — بحث ہی ان کا طریقہ ہے۔
۴۔ ’’يَقُولُ الَّذِينَ كَفَرُوا إِنْ هَٰذَا إِلَّا أَسَاطِيرُ الْأَوَّلِينَ‘‘ — کافر کہتے ہیں: یہ سوائے پچھلوں کی کہانیوں کے کچھ نہیں — یعنی وہ — قرآن کو — پچھلوں کی کہانیاں — کہہ دیتے ہیں — یہ ان کا بہانہ ہے۔
۵۔ عملی سبق: حق سننے پر سمجھ کر عمل کرو؛ ہٹ دھرمی سے بچو۔"""
),
815: (
"اور وہ — اس (قرآن) سے — روکتے ہیں — اور خود بھی اس سے دور رہتے ہیں — اور وہ نہیں ہلاک کرتے سوائے اپنے آپ کو — اور انہیں شعور نہیں ہوتا",
"""۱۔ کفار — روکتے بھی ہیں اور دور بھی رہتے ہیں۔
۲۔ ’’وَهُمْ يَنْهَوْنَ عَنْهُ وَيَنْأَوْنَ عَنْهُ وَإِن يُهْلِكُونَ إِلَّا أَنفُسَهُمْ وَمَا يَشْعُرُونَ‘‘ — اور وہ — اس (قرآن) سے — روکتے ہیں — اور خود بھی اس سے دور رہتے ہیں — اور وہ نہیں ہلاک کرتے سوائے اپنے آپ کو — اور انہیں شعور نہیں ہوتا — یعنی کفار کا ہر نقصان — خود انہی کا نقصان ہے۔
۳۔ عملی سبق: قرآن سے روکنے والوں سے بچو؛ قرآن کو اپنی زندگی بناؤ۔"""
),
816: (
"اور — کاش تم ان کو — دیکھتے — جب انہیں آگ کے سامنے روکا جائے گا — وہ کہیں گے: ہائے — کاش ہم — واپس بھیجے جائیں — اور ہم اپنے رب کی نشانیوں کو نہ جھٹلاتے — اور ہم — مومنوں — میں سے ہوتے",
"""۱۔ جہنم کے دروازے پر — واپسی کی تمنا۔
۲۔ ’’وَلَوْ تَرَىٰ إِذْ وُقِفُوا عَلَى النَّارِ فَقَالُوا يَا لَيْتَنَا نُرَدُّ وَلَا نُكَذِّبَ بِآيَاتِ رَبِّنَا وَنَكُونَ مِنَ الْمُؤْمِنِينَ‘‘ — اور — کاش تم ان کو — دیکھتے — جب انہیں آگ کے سامنے روکا جائے گا — وہ کہیں گے: ہائے — کاش ہم — واپس بھیجے جائیں — اور ہم اپنے رب کی نشانیوں کو نہ جھٹلاتے — اور ہم — مومنوں — میں سے ہوتے — یعنی قیامت کے دن — تمنا بے فائدہ ہوگی۔
۳۔ عملی سبق: بروقت ایمان لاؤ؛ تمنا ہمیشہ بے سود ہے۔"""
),
817: (
"بلکہ — ان کے سامنے وہ ظاہر ہو گیا جو وہ پہلے چھپاتے تھے — اور اگر — وہ — واپس بھیجے جائیں — تو وہ — ضرور — اُسی کی طرف لوٹ جائیں جس سے انہیں روکا گیا — اور بے شک وہ — جھوٹے — ہیں",
"""۱۔ جہنم کے دروازے پر — سچی تمنا بھی نہیں۔
۲۔ ’’بَل بَدَا لَهُم مَّا كَانُوا يُخْفُونَ مِن قَبْلُ وَلَوْ رُدُّوا لَعَادُوا لِمَا نُهُوا عَنْهُ وَإِنَّهُمْ لَكَاذِبُونَ‘‘ — بلکہ — ان کے سامنے وہ ظاہر ہو گیا جو وہ پہلے چھپاتے تھے — اور اگر — وہ — واپس بھیجے جائیں — تو وہ — ضرور — اُسی کی طرف لوٹ جائیں جس سے انہیں روکا گیا — اور بے شک وہ — جھوٹے — ہیں — یعنی ان کا خوف بھی عارضی تھا — اپنی عادت سے نہیں بدلیں گے۔
۳۔ عملی سبق: بروقت اپنی عادتیں سنوارو؛ اللہ کا خوف مستقل رکھو۔"""
),
818: (
"اور وہ کہتے ہیں: سوائے — ہماری — دنیاوی زندگی کے — کوئی اور زندگی نہیں — اور ہم — کبھی — دوبارہ — نہیں اٹھائے جائیں گے",
"""۱۔ منکرینِ آخرت — دنیا پر ایمان۔
۲۔ ’’وَقَالُوا إِنْ هِيَ إِلَّا حَيَاتُنَا الدُّنْيَا وَمَا نَحْنُ بِمَبْعُوثِينَ‘‘ — اور وہ کہتے ہیں: سوائے — ہماری — دنیاوی زندگی کے — کوئی اور زندگی نہیں — اور ہم — کبھی — دوبارہ — نہیں اٹھائے جائیں گے — یعنی آخرت سے انکار — ان کی غلطی۔
۳۔ عملی سبق: آخرت کو مانو؛ دنیا کی زندگی — عارضی ہے۔"""
),
819: (
"اور — کاش تم ان کو — دیکھتے — جب انہیں — اپنے — رب کے سامنے روکا جائے گا — (وہ) کہے گا: کیا یہ — (قیامت) — حق نہیں — وہ کہیں گے: ہاں — ہمارے — رب کی — قسم — (وہ) کہے گا: پس عذاب چکھ لو — اس وجہ سے جو تم کفر کرتے تھے",
"""۱۔ قیامت کے دن — اللہ کے سامنے اقرار۔
۲۔ ’’وَلَوْ تَرَىٰ إِذْ وُقِفُوا عَلَىٰ رَبِّهِمْ قَالَ أَلَيْسَ هَٰذَا بِالْحَقِّ‘‘ — اور — کاش تم ان کو — دیکھتے — جب انہیں — اپنے — رب کے سامنے روکا جائے گا — (وہ) کہے گا: کیا یہ — (قیامت) — حق نہیں — یعنی قیامت کے دن — اللہ خود سوال کرے گا۔
۳۔ ’’قَالُوا بَلَىٰ وَرَبِّنَا قَالَ فَذُوقُوا الْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ‘‘ — وہ کہیں گے: ہاں — ہمارے — رب کی — قسم — (وہ) کہے گا: پس عذاب چکھ لو — اس وجہ سے جو تم کفر کرتے تھے — یعنی انکار کا انجام — عذاب۔
۴۔ عملی سبق: آخرت کو حق مانو؛ اللہ کا خوف کرو۔"""
),
820: (
"وہ — یقینی — ہار گئے جنہوں نے جھٹلایا — اللہ سے — ملاقات — یہاں تک کہ ان پر — اچانک — قیامت — آ گئی — وہ کہیں گے: ہائے ہماری — افسوس! اس پر جو ہم نے — کوتاہی کی — اور وہ اپنے گناہ — اپنی — پیٹھوں پر — اٹھائے ہوئے ہیں — دیکھو — برا ہے جو وہ اٹھا رہے ہیں",
"""۱۔ اللہ سے ملاقات کی تکذیب — قیامت پر — ہلاکت۔
۲۔ ’’قَدْ خَسِرَ الَّذِينَ كَذَّبُوا بِلِقَاءِ اللّٰہِ حَتَّىٰ إِذَا جَاءَتْهُمُ السَّاعَۃُ بَغْتَۃً‘‘ — وہ — یقینی — ہار گئے جنہوں نے جھٹلایا — اللہ سے — ملاقات — یہاں تک کہ ان پر — اچانک — قیامت — آ گئی — یعنی قیامت — اچانک آئے گی۔
۳۔ ’’قَالُوا يَا حَسْرَتَنَا عَلَىٰ مَا فَرَّطْنَا فِيهَا وَهُمْ يَحْمِلُونَ أَوْزَارَهُمْ عَلَىٰ ظُهُورِهِمْ‘‘ — وہ کہیں گے: ہائے ہماری — افسوس! اس پر جو ہم نے — اس میں — کوتاہی کی — اور وہ اپنے گناہ — اپنی — پیٹھوں پر — اٹھائے ہوئے ہیں — یعنی گناہ کا بوجھ — قیامت میں اپنی پیٹھ پر — باقاعدہ — ہوگا۔
۴۔ ’’أَلَا سَاءَ مَا يَزِرُونَ‘‘ — دیکھو — برا ہے جو وہ اٹھا رہے ہیں — یعنی گناہ کا بوجھ — بہت برا ہے۔
۵۔ عملی سبق: اللہ سے ملاقات کو جھٹلاؤ مت؛ قیامت کی تیاری کرو؛ گناہ کا بوجھ کم کرو۔"""
),
821: (
"اور دنیاوی زندگی — سوائے — کھیل اور — تھکان — کے — کچھ نہیں — اور — یقیناً — آخرت کا گھر — ان لوگوں کے لیے جو پرہیزگار ہیں — بہتر ہے — کیا تم نہیں سمجھتے",
"""۱۔ دنیا — محدود — عارضی — آخرت — مستقل — بہتر۔
۲۔ ’’وَمَا الْحَيَاةُ الدُّنْيَا إِلَّا لَعِبٌ وَلَهْوٌ وَلَلدَّارُ الْآخِرَۃُ خَيْرٌ لِّلَّذِينَ يَتَّقُونَ‘‘ — اور دنیاوی زندگی — سوائے — کھیل اور — تھکان — کے — کچھ نہیں — اور — یقیناً — آخرت کا گھر — ان لوگوں کے لیے جو پرہیزگار ہیں — بہتر ہے — یعنی دنیا — ایک کھیل ہے — آخرت — مستقل بہتر ہے۔
۳۔ ’’أَفَلَا تَعْقِلُونَ‘‘ — کیا تم نہیں سمجھتے — یعنی عقل کا تقاضا ہے آخرت کو فوقیت دو۔
۴۔ عملی سبق: دنیا کو مقصد نہ بناؤ؛ آخرت کو اپنی منزل سمجھو۔"""
),
822: (
"ہمیں — یقیناً — یہ معلوم ہے کہ — جو — وہ کہتے ہیں — اس سے آپ غمگین ہوتے ہیں — پس وہ — درحقیقت — آپ کو نہیں جھٹلاتے — لیکن — ظالم لوگ — اللہ کی آیات — کا — انکار کرتے ہیں",
"""۱۔ نبی ﷺ — غمگین نہ ہوں — کفار آیات کا انکار کرتے ہیں۔
۲۔ ’’قَدْ نَعْلَمُ إِنَّهُ لَيَحْزُنُكَ الَّذِي يَقُولُونَ‘‘ — ہمیں — یقیناً — یہ معلوم ہے کہ — جو — وہ کہتے ہیں — اس سے آپ غمگین ہوتے ہیں — یعنی اللہ نبی ﷺ کے غم سے واقف ہے۔
۳۔ ’’فَإِنَّهُمْ لَا يُكَذِّبُونَكَ وَلَٰكِنَّ الظَّالِمِينَ بِآيَاتِ اللّٰہِ يَجْحَدُونَ‘‘ — پس وہ — درحقیقت — آپ کو نہیں جھٹلاتے — لیکن — ظالم لوگ — اللہ کی آیات — کا — انکار کرتے ہیں — یعنی کفار دل میں جان چکے تھے کہ نبی ﷺ سچے ہیں — مگر ضد کی وجہ سے انکار کرتے تھے۔
۴۔ عملی سبق: حق پہچان کر اس کا انکار مت کرو؛ ظلم سے بچو۔"""
),
}
